#!/bin/bash
# KV-PEER5 2026-10-19: member wrapper input-stage bench (tb_<member>_stage.sv, generated by
# tools/qwen_kv_die/host_cluster/gen_peer_rr.py): <member>_rr vs the unchanged <member> with the same reset relay and the
# staged inputs delayed one edge in the bench, every output every edge.
#   usage: run_hr_peer_stage.sh OUT MEMBER [MUT] [SEED]   MUT 1 = -DQKD_HR_PE_STAGE_MUTANT (stage bypassed; must FAIL)
# Sources: the qkd_hr_core_peer kit's RTL list (physical/ref_tile/qkd_hr_core_peer/spec.json). Verilator 5.050 unless VERILATOR.
set -u
cd "$(dirname "$0")/../../../.."
O=${1:?out}; M=${2:?member}; m=${3:-0}; s=${4:-1019}; mkdir -p "$O"
V=${VERILATOR:-$HOME/.local/opentallas-tools/verilator-5.050/bin/verilator}
d=""; [ "$m" = 1 ] && d="-DQKD_HR_PE_STAGE_MUTANT"
T=rtl/test/qwen_host/hr_peer_stage_1019/tb_${M}_stage.sv
S=$(python3 -c "import json;print(' '.join(json.load(open('physical/ref_tile/qkd_hr_core_peer/spec.json'))['sources']))")
$V --version
$V --binary --timing -Wno-fatal -Wno-lint -Wno-style -Wno-TIMESCALEMOD -j 8 $d -GSEED=$s --top-module tb_${M}_stage \
  -Mdir "$O/obj$m" $T $S > "$O/build$m.log" 2>&1 || { echo "HR_PEER_STAGE $M BUILD-ERR"; tail -30 "$O/build$m.log"; exit 1; }
r=$("$O/obj$m/Vtb_${M}_stage" | tee "$O/run$m.log" | grep -E "^HR_PEER_STAGE $M .*(PASS|FAIL)\$" | tail -1)
echo "$r"
case "$r" in *" PASS") exit 0;; *) exit 1;; esac
